"use client";

import Image from "next/image";
import { useId, useState } from "react";

import { uploadImage, type MediaPurpose, type UploadedMedia } from "@/lib/upload";
import styles from "./upload.module.css";

interface ImageUploadFieldProps {
  label: string;
  purpose: MediaPurpose;
  currentUrl?: string | null;
  shape?: "circle" | "square" | "cover";
  value: UploadedMedia | null;
  onChange: (media: UploadedMedia | null) => void;
  disabled?: boolean;
}

export default function ImageUploadField({
  label,
  purpose,
  currentUrl,
  shape = "square",
  value,
  onChange,
  disabled,
}: ImageUploadFieldProps) {
  const inputID = useId();
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState("");
  const fallback = purpose === "GROUP_IMAGE" ? "/group-placeholder.svg" : "/image-placeholder.svg";
  const preview = value?.url || currentUrl || fallback;

  async function select(file?: File) {
    if (!file) return;
    setUploading(true);
    setError("");
    try {
      onChange(await uploadImage(file, purpose));
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Falha no upload.");
    } finally {
      setUploading(false);
    }
  }

  return (
    <div className={styles.field}>
      <span>{label}</span>
      <div className={styles.row}>
        <Image
          className={`${styles.preview} ${styles[shape]}`}
          src={preview}
          alt="Prévia da imagem"
          width={shape === "cover" ? 112 : 96}
          height={shape === "cover" ? 168 : 96}
          unoptimized
        />
        <div>
          <label className={styles.button} htmlFor={inputID} aria-disabled={disabled || uploading}>
            {uploading ? "Enviando…" : value ? "Trocar seleção" : "Selecionar imagem"}
          </label>
          <input
            id={inputID}
            type="file"
            accept="image/jpeg,image/png,image/webp"
            disabled={disabled || uploading}
            onChange={(event) => void select(event.target.files?.[0])}
          />
          <small>JPG, PNG ou WebP. A imagem é validada e convertida para WebP.</small>
        </div>
      </div>
      {error && <p className={styles.error}>{error}</p>}
    </div>
  );
}
